// ═══ HORARIO DE LLAMADAS INDIA: 11:00–19:00 IST (UTC+5:30) ═══
const istMinutes = (new Date().getUTCHours() * 60 + new Date().getUTCMinutes() + 330) % 1440;
const IST_OPEN = 11 * 60, IST_CLOSE = 19 * 60;
if (istMinutes < IST_OPEN || istMinutes >= IST_CLOSE) {
  const h = String(Math.floor(istMinutes / 60)).padStart(2, '0');
  const m = String(istMinutes % 60).padStart(2, '0');
  console.log(`🌙 Fuera de horario India (${h}:${m} IST) — sin llamadas hasta las 11:00 IST`);
  return [];
}

function toE164(raw) {
  if (raw === undefined || raw === null) return '';
  let p = String(raw).replace(/[^0-9+]/g, '');
  if (!p) return '';
  if (p.startsWith('+')) return p;
  if (p.length >= 8 && p.length <= 15) return '+' + p;
  return '';
}

const SKIP_STATUSES = new Set([
  'DO_NOT_CALL', 'CONVERTED', 'MAX_ATTEMPTS_REACHED',
  'INTERESTED', 'NOT_INTERESTED', 'SALES_HANDOFF', 'ACCOUNT_OPENED',
  'SUCCESSFUL', 'VOICEMAIL', 'FAILED', 'SCHEDULED'
]);

const BATCH_SIZE = 5;
const RETRY_COOLDOWN_MIN = 5;
const STUCK_TIMEOUT_MIN = 30;
const now = Date.now();
const attempts = [];
const skipped = [];

for (const item of $input.all()) {
  const r = { ...(item.json || {}) };
  const phone = toE164(r.phone);
  let attemptsCount = Number(r.call_attempts || 0);
  let status = String(r.status || '').trim().toUpperCase();

  if (!phone) { skipped.push({ lead_id: r.lead_id, reason: `bad phone: '${r.phone}'` }); continue; }
  if (!r.lead_id || String(r.lead_id).trim() === '') { skipped.push({ lead_id: 'EMPTY', reason: 'missing lead_id' }); continue; }

  if ((status === 'CALL_IN_PROGRESS' || status === 'DIALING') && r.last_call_time) {
    const minsSince = (now - new Date(r.last_call_time).getTime()) / 60000;
    if (minsSince > STUCK_TIMEOUT_MIN) {
      status = 'READY_TO_CALL'; r.status = 'READY_TO_CALL';
    } else {
      skipped.push({ lead_id: r.lead_id, reason: `${status} since ${minsSince.toFixed(0)}min` }); continue;
    }
  }

  if ((status === 'DIAL_FAILED') && r.last_call_time) {
    const minsSince = (now - new Date(r.last_call_time).getTime()) / 60000;
    if (minsSince < RETRY_COOLDOWN_MIN) {
      skipped.push({ lead_id: r.lead_id, reason: `DIAL_FAILED cooldown ${minsSince.toFixed(1)}min` }); continue;
    }
    status = 'READY_TO_CALL'; r.status = 'READY_TO_CALL';
  }

  if (attemptsCount >= 3) { skipped.push({ lead_id: r.lead_id, reason: `attempts=${attemptsCount}` }); continue; }
  if (SKIP_STATUSES.has(status)) { skipped.push({ lead_id: r.lead_id, reason: `status=${status}` }); continue; }
  if (status === 'SCHEDULED') { skipped.push({ lead_id: r.lead_id, reason: 'SCHEDULED → WF4' }); continue; }

  r.phone = phone;
  r.full_name = String(r.full_name || '').trim() || 'User';
  r.lead_id = String(r.lead_id).trim();

  const phoneStr = String(phone);
  let country = String(r.country || '').trim();
  if (!country || country.length < 2) {
    if (phoneStr.startsWith('+91')) country = 'India';
    else if (phoneStr.startsWith('+971')) country = 'UAE';
    else country = 'India';
  }
  r.country = country;
  attempts.push({ json: r });
}

console.log('🟢 ELEGIBLES', attempts.length, '| ⚪ SKIPPED', skipped.length);
if (attempts.length === 0) return [];

const nuevos     = attempts.filter(a => Number(a.json.call_attempts || 0) === 0);
const reintentos = attempts.filter(a => Number(a.json.call_attempts || 0) > 0);
const batch = [...nuevos, ...reintentos].slice(0, BATCH_SIZE);

console.log(`📦 Batch: ${batch.length}/${BATCH_SIZE} | Nuevos: ${nuevos.length} | Reintentos: ${reintentos.length}`);
return batch;

// Genera JWT de Stringee con HS256
// Válido por 1 hora — se regenera en cada ejecución
const crypto = require('crypto');

const SID = 'AC50a1aa324d52698728ae498e5d34386a';
const KEY = 'SEWgD8mlmbshvT87T7F7Czdd5k8JdWdp';
const now = Math.floor(Date.now() / 1000);
const exp = now + 3600; // 1 hora

const header  = Buffer.from(JSON.stringify({ typ:'JWT', alg:'HS256', cty:'stringee-api;v=1' })).toString('base64url');
const payload = Buffer.from(JSON.stringify({ jti: SID + '_' + now, iss: SID, exp, rest_api: true })).toString('base64url');
const sig     = crypto.createHmac('sha256', KEY).update(header + '.' + payload).digest('base64url');
const jwt     = header + '.' + payload + '.' + sig;

console.log('🔑 Stringee JWT generado (exp en 1h)');
return [{ json: { jwt } }];

// Llama a Stringee API para cada lead del batch.
// El answer_url incluye lead_id y phone como query params
// para que el webhook de Stringee-Answer pueda identificar al lead
// y WF-Stringee-Init pueda devolver los dynamic_variables a ElevenLabs.
const jwt    = $('⚙️ Generate Stringee JWT').first().json.jwt;
const leads  = $('⚙️ Normalize & Select').all();
const ANSWER_BASE = 'https://landmarket-n8n.dhsoig.easypanel.host/webhook/stringee-answer';
const FROM_NUMBER = '917971441787';
const results = [];

for (const item of leads) {
  const lead  = item.json;
  const phone = String(lead.phone || '').replace(/^\+/, ''); // sin + para Stringee
  const answerUrl = ANSWER_BASE + '?lead_id=' + encodeURIComponent(lead.lead_id) + '&phone=' + encodeURIComponent(lead.phone);

  const body = {
    from: { type: 'external', number: FROM_NUMBER, alias: FROM_NUMBER },
    to: [{ type: 'external', number: phone, alias: phone }],
    answer_url: answerUrl
  };

  console.log('📞 Stringee callout → ', phone, '| lead_id:', lead.lead_id);

  let resp, statusCode, callId = '';
  try {
    resp = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.stringee.com/v1/call2/callout',
      headers: {
        'Content-Type': 'application/json',
        'X-STRINGEE-AUTH': jwt
      },
      body: JSON.stringify(body),
      returnFullResponse: true,
      timeout: 30000
    });
    statusCode = resp.statusCode || 200;
    const parsed = typeof resp.body === 'string' ? JSON.parse(resp.body) : resp.body;
    callId = String(parsed.call_id || parsed.callId || parsed.data?.call_id || '');
    console.log('✅ Stringee response:', statusCode, '| call_id:', callId, '| r:', parsed.r);
  } catch(e) {
    statusCode = 500;
    console.error('🔴 Stringee error:', e.message);
  }

  results.push({ json: {
    lead_id:              lead.lead_id,
    phone:                lead.phone,
    stringee_call_id:     callId,
    stringee_status_code: statusCode,
    lead_json:            lead
  }});
}

return results;

// Clasifica el resultado del callout de Stringee
// r=0 en Stringee significa éxito (igual que HTTP 200 en ElevenLabs)
const items = $input.all();
const now   = new Date().toISOString();
const cooldownDate = new Date(Date.now() + 3 * 60 * 60 * 1000).toISOString();

return items.map(item => {
  const r    = item.json;
  const lead = r.lead_json || {};
  const ok   = r.stringee_status_code >= 200 && r.stringee_status_code < 300 && r.stringee_call_id;

  let status, last_call_status, notes, callback_date;
  if (ok) {
    status           = 'CALL_IN_PROGRESS';
    last_call_status = 'INITIATED';
    notes            = '🟢 Stringee call sent: ' + r.stringee_call_id;
    callback_date    = '';
  } else {
    status           = 'DIAL_FAILED';
    last_call_status = 'HTTP_' + r.stringee_status_code;
    notes            = '🔴 Stringee ' + r.stringee_status_code;
    callback_date    = cooldownDate;
  }

  console.log('📊 Classify | lead_id:', lead.lead_id, '| status:', status, '| call_id:', r.stringee_call_id);

  return { json: {
    lead_id:          lead.lead_id,
    elevenlabs_call_id: r.stringee_call_id,  // reutilizamos la misma columna
    status,
    last_call_status,
    notes,
    callback_date,
    call_attempts:    Number(lead.call_attempts || 0) + 1,
    last_call_time:   now
  }};
});
